def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive = []
    for oid, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append((oid, opp))

    if not alive:
        safe = DAILY_SALARY * 0.35
        if no_water_days >= 1 or hp <= 3:
            safe = DAILY_SALARY * 0.75
        return float(max(0.0, min(budget, safe)))

    total_players = 1 + len(alive)
    est_units = int(supply // WATER_REQ)
    scarcity = est_units < total_players
    severe_scarcity = est_units <= max(0, total_players - 2)

    opp_bids = []
    strong_pressure = 0.0
    needy_pressure = 0.0
    for oid, opp in alive:
        prev = opp.get('previous_trace') or {}
        bid = prev.get('bid')
        if bid is not None:
            b = float(bid)
            opp_bids.append(b)
            if b > strong_pressure:
                strong_pressure = b
            if opp.get('no_water_days', 0) >= 1 or opp.get('hp', 10) <= 3:
                if b > needy_pressure:
                    needy_pressure = b

    if opp_bids:
        avg_opp = sum(opp_bids) / len(opp_bids)
        max_opp = max(opp_bids)
    else:
        avg_opp = DAILY_SALARY * 0.6
        max_opp = DAILY_SALARY * 0.8

    urgency = 0
    if no_water_days >= 2:
        urgency += 3
    elif no_water_days == 1:
        urgency += 2
    if hp <= 2:
        urgency += 3
    elif hp <= 4:
        urgency += 2
    elif hp <= 6:
        urgency += 1
    if severe_scarcity:
        urgency += 2
    elif scarcity:
        urgency += 1

    if urgency >= 5:
        target = max(max_opp + 2.0, needy_pressure + 3.0, DAILY_SALARY * 1.55)
    elif urgency >= 3:
        target = max(avg_opp + 3.0, needy_pressure + 2.0, DAILY_SALARY * 1.15)
    elif scarcity:
        target = max(avg_opp * 0.92, DAILY_SALARY * 0.82)
    else:
        if supply >= 24:
            target = DAILY_SALARY * 0.22
        elif supply >= 21:
            target = DAILY_SALARY * 0.32
        elif supply >= 18:
            target = DAILY_SALARY * 0.48
        else:
            target = DAILY_SALARY * 0.62

    if day >= 8 and hp >= 7 and no_water_days == 0 and not severe_scarcity:
        target *= 0.9

    reserve_floor = 0.0
    if day <= 7:
        reserve_floor = max(0.0, budget - DAILY_SALARY * (10 - day) * 0.9)
        target = max(target, min(budget, reserve_floor))

    bid = min(budget, target)
    if bid < 0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    EPISODE_DAYS = 10

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        if day_context['supply'] < WATER_REQ:
            return max(1.0, min(my_status['budget'], DAILY_SALARY * 0.1))
        return max(1.0, min(my_status['budget'], DAILY_SALARY * 0.5))

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    base_bid = float(DAILY_SALARY)

    if my_status['hp'] <= 1: 
        bid = base_bid * 1.3 
    elif my_status['hp'] <= 3: 
        bid = base_bid * 1.1 
    else: 
        bid = base_bid * 0.95 

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= base_bid * 1.05:
            if my_status['hp'] <= 3: 
                bid = max(bid, highest_prev_bid + 5.0)
            else: 
                bid = max(bid, highest_prev_bid + 1.0)
        elif highest_prev_bid < base_bid * 0.8:
            if my_status['hp'] > 3: 
                bid = min(bid, base_bid * 0.8)

    num_active_opponents = len(alive_opponents)
    total_players = num_active_opponents + 1
    avg_water_if_split = day_context['supply'] / total_players

    if avg_water_if_split < WATER_REQ * 0.8:
        if my_status['hp'] <= 3: 
            bid = max(bid, base_bid * 1.15)
        elif my_status['hp'] > 3: 
            bid = max(bid, base_bid * 1.05)
    elif avg_water_if_split >= WATER_REQ * 1.5:
        if my_status['hp'] > 3: 
            bid = min(bid, base_bid * 0.75)

    bid = max(1.0, bid)
    final_bid = min(my_status['budget'], bid)

    if day_context['day'] == EPISODE_DAYS - 1:
        if my_status['hp'] >= 1: 
            if my_status['budget'] >= base_bid * 1.0:
                final_bid = max(final_bid, base_bid * 1.2)
            else: 
                final_bid = my_status['budget']
        else: 
            final_bid = 1.0 

    return final_bid

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(budget, DAILY_SALARY * 0.4)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    max_prev_bid = max(yesterday_bids) if yesterday_bids else 0

    # Low hp: bid high to survive
    if hp <= 2 or no_water_days >= 1:
        bid = min(budget, DAILY_SALARY * 0.95)
        return max(0, int(bid))

    # Supply scarcity: outbid yesterday's max
    if supply < 18:
        target = max_prev_bid + 2
        if target < DAILY_SALARY * 0.6:
            target = DAILY_SALARY * 0.6
        bid = min(budget, target)
    else:
        # Normal supply: bid moderately
        if yesterday_bids:
            base = max(DAILY_SALARY * 0.5, max_prev_bid * 0.9)
        else:
            base = DAILY_SALARY * 0.5
        bid = min(budget, base)

    return max(0, int(bid))

